"""解析测试台标准输出中的单行结果。

支持三类记录（均为单行，名称为去除首尾空白后非空的单个 token）：

- ``ASSERT PASS name``
- ``ASSERT FAIL name message``（message 为 name 之后的全部文本，可为空）
- ``COVER name``

断言状态取最后一次结果；失败次数按 FAIL 记录累加；
覆盖率点按命中次数累加。所有映射均按名称首次出现的顺序保存。
"""

import re

#: 三类记录的标记前缀。
ASSERT_PREFIX = "ASSERT PASS "
ASSERT_FAIL_PREFIX = "ASSERT FAIL "
COVER_PREFIX = "COVER "

#: 名称为首个非空白 token；FAIL 的 message 为名称之后的全部文本。
_PASS_RE = re.compile(r"^ASSERT\s+PASS\s+(\S+)\s*$")
_FAIL_RE = re.compile(r"^ASSERT\s+FAIL\s+(\S+)(?:\s+(.*?))?\s*$")
_COVER_RE = re.compile(r"^COVER\s+(\S+)\s*$")


class ResultCollector:
    """按行收集断言与覆盖率结果。"""

    def __init__(self):
        #: name -> {"status": "passed"/"failed", "fail_count": int}
        self.assertions = {}
        #: name -> 命中次数
        self.coverage = {}

    def feed_line(self, line):
        """处理一行（不含行尾换行）。无法识别的行将被忽略。

        标记与名称之间允许任意空白（空格或制表符）。

        :returns: 识别出的记录元组（仅供调试），未识别返回 None。
        """
        fail = _FAIL_RE.match(line)
        if fail:
            name = fail.group(1)
            message = fail.group(2) or ""
            entry = self.assertions.setdefault(
                name, {"status": "failed", "fail_count": 0}
            )
            entry["status"] = "failed"
            entry["fail_count"] += 1
            return ("assert_fail", name, message)

        pas = _PASS_RE.match(line)
        if pas:
            name = pas.group(1)
            entry = self.assertions.setdefault(
                name, {"status": "passed", "fail_count": 0}
            )
            entry["status"] = "passed"
            return ("assert_pass", name)

        cov = _COVER_RE.match(line)
        if cov:
            name = cov.group(1)
            self.coverage[name] = self.coverage.get(name, 0) + 1
            return ("cover", name)

        return None

    def feed_text(self, text):
        """处理整段文本，按 \\n / \\r\\n 分行。"""
        for raw in text.splitlines():
            self.feed_line(raw)

    @property
    def has_failure(self):
        """是否出现过且最终仍处于失败状态的断言。"""
        return any(a["status"] == "failed" for a in self.assertions.values())

"""ASSERT/COVER 输出解析单测。"""

from rtl_lab.parser import ResultCollector


def test_pass_and_cover():
    c = ResultCollector()
    c.feed_text("ASSERT PASS a\nCOVER b\n")
    assert c.assertions == {"a": {"status": "passed", "fail_count": 0}}
    assert c.coverage == {"b": 1}


def test_fail_records_message_and_count():
    c = ResultCollector()
    c.feed_line("ASSERT FAIL f expected 1 got 0")
    entry = c.assertions["f"]
    assert entry["status"] == "failed"
    assert entry["fail_count"] == 1


def test_last_result_wins():
    c = ResultCollector()
    c.feed_line("ASSERT FAIL x msg")
    c.feed_line("ASSERT PASS x")
    assert c.assertions["x"]["status"] == "passed"
    assert c.assertions["x"]["fail_count"] == 1
    assert c.has_failure is False


def test_fail_after_pass_is_final_failure():
    c = ResultCollector()
    c.feed_line("ASSERT PASS x")
    c.feed_line("ASSERT FAIL x again")
    assert c.has_failure is True
    assert c.assertions["x"]["fail_count"] == 1


def test_repeated_fail_accumulates():
    c = ResultCollector()
    for _ in range(3):
        c.feed_line("ASSERT FAIL x boom")
    assert c.assertions["x"]["fail_count"] == 3


def test_cover_hit_count():
    c = ResultCollector()
    c.feed_text("COVER c1\nCOVER c1\nCOVER c2\n")
    assert c.coverage == {"c1": 2, "c2": 1}


def test_first_seen_order_preserved():
    c = ResultCollector()
    c.feed_text("ASSERT PASS z\nCOVER aa\nASSERT FAIL a m\nCOVER bb\n")
    assert list(c.assertions) == ["z", "a"]
    assert list(c.coverage) == ["aa", "bb"]


def test_blank_and_whitespace_names_ignored():
    c = ResultCollector()
    for line in ("ASSERT PASS   ", "ASSERT FAIL   ", "COVER  ",
                 "ASSERT PASS", "ASSERT FAIL", "COVER"):
        assert c.feed_line(line) is None
    assert c.assertions == {}
    assert c.coverage == {}


def test_unrelated_lines_ignored():
    c = ResultCollector()
    assert c.feed_line("ASSERT PASSING nope") is None
    assert c.feed_line("VCD warning") is None
    assert c.feed_line("ASSERT PASS real_one") is not None
    assert list(c.assertions) == ["real_one"]


def test_crlf_and_tabs():
    c = ResultCollector()
    c.feed_text("ASSERT PASS\ta\r\nCOVER\tb\r\n")
    assert "a" in c.assertions
    assert c.coverage == {"b": 1}


def test_no_coverage_is_not_failure():
    c = ResultCollector()
    c.feed_line("ASSERT PASS a")
    assert c.has_failure is False
    assert c.coverage == {}

