    records = []
    for key, value in results.items():
        if not isinstance(value, dict):
            raise RuntimeError(f"测试 {key!r} 的结果必须是 dict")
        embedded = value.get("name")
        if embedded is not None and embedded != key:
            raise RuntimeError(
                f"测试结果命名冲突：归属键 {key!r} 与结果名称 "
                f"{embedded!r} 不一致"
