        raise RuntimeError("测试结果必须是 dict")
    name = result.get("name")
    if not isinstance(name, str) or not name.strip():
        raise RuntimeError("存在缺少名称的测试结果")
    if name not in expected_set:
        raise RuntimeError(
            f"测试结果 {name!r} 不属于本次运行（run_id={run_id!r}）"
